 public static JSONObject readiness(JSONObject input,String now,boolean acknowledged)throws Exception{try{return checked(input,time(now),acknowledged);}catch(Exception e){return object("canPrepare",false,"issues",new JSONArray().put(e.getMessage()),"heldPositions",JSONObject.NULL,"automaticTrading",false);}}
